/*
    Peaceful Shell-Expansion Morph
    Among Letters N -> E -> O -> N

    - Total cycle: 12 seconds
    - Each pair morph: 4 seconds
    - Perfect loop: no glitch at wrap
    - Cosine easing for gentle motion
    - Pastel coloring

    Enjoy!
*/

#ifdef GL_ES
precision mediump float;
#endif

//-----------------------------------------------------
// Distance / SDF Helpers
//-----------------------------------------------------

// Distance from point p to line segment (a->b).
float lineSegmentDist(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0.0, 1.0);
    return length(pa - ba*h);
}

// Signed distance for a stroke around a line segment.
float lineSegmentSDF(vec2 p, vec2 a, vec2 b, float halfWidth)
{
    return lineSegmentDist(p, a, b) - halfWidth;
}

// A ring SDF: negative if inside ring stroke, positive otherwise.
float ringSDF(vec2 p, float radius, float halfThickness)
{
    float d = length(p) - radius;
    return abs(d) - halfThickness;
}

// Smooth union of two SDFs.
float opSmoothUnion(float d1, float d2, float k)
{
    // Larger k => softer blending
    float h = clamp(0.5 + 0.5*(d2 - d1)/k, 0.0, 1.0);
    return mix(d2, d1, h) - k*h*(1.0 - h);
}

//-----------------------------------------------------
// Letters (N, E, O) SDF
// Each letter ~[-0.15..+0.15] in x, ~[-0.25..+0.25] in y
//-----------------------------------------------------
float letterN(vec2 p)
{
    // Left bar: top -> bottom
    float dLeft  = lineSegmentSDF(p, vec2(-0.15,  0.25), vec2(-0.15, -0.25), 0.02);
    // Right bar: top -> bottom
    float dRight = lineSegmentSDF(p, vec2( 0.15,  0.25), vec2( 0.15, -0.25), 0.02);
    // Diagonal: top-left -> bottom-right
    float dDiag  = lineSegmentSDF(p, vec2(-0.15,  0.25), vec2( 0.15, -0.25), 0.02);

    return min(dLeft, min(dRight, dDiag));
}


float letterE(vec2 p)
{
    float dVert = lineSegmentSDF(p, vec2(-0.15, -0.25), vec2(-0.15,  0.25), 0.02);
    float dTop  = lineSegmentSDF(p, vec2(-0.15,  0.25), vec2( 0.15,  0.25), 0.02);
    float dMid  = lineSegmentSDF(p, vec2(-0.15,  0.00), vec2( 0.10,  0.00), 0.02);
    float dBot  = lineSegmentSDF(p, vec2(-0.15, -0.25), vec2( 0.15, -0.25), 0.02);
    return min(dVert, min(dTop, min(dMid, dBot)));
}

float letterO(vec2 p)
{
    // O: ring with radius=0.20, thickness=0.04
    return ringSDF(p, 0.20, 0.02);
}

// Master letter SDF: 0->N, 1->E, 2->O
float letterSDF(vec2 p, int idx)
{
    if (idx == 0) return letterN(p);
    if (idx == 1) return letterE(p);
    return letterO(p);
}

//-----------------------------------------------------
// Shell-Expansion Morph
//-----------------------------------------------------
/*
  shapeMorph(dA, dB, t):
    - Push shape A outward by +t*offset => recede
    - Pull shape B inward by +(1-t)*offset => appear
    - Then apply a smooth union.

  Larger offsets => bigger shell expansions.
  Larger kSmooth => more softness in the union.
*/
float shapeMorph(float dA, float dB, float t)
{
    float fadeOutOffset = 0.8; 
    float fadeInOffset  = 0.8; 
    float kSmooth       = 0.5; 

    float dA_ = dA + t * fadeOutOffset;        // push A out
    float dB_ = dB + (1.0 - t) * fadeInOffset; // pull B in

    return opSmoothUnion(dA_, dB_, kSmooth);
}

//-----------------------------------------------------
// MAIN
//-----------------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized coords in [-1..+1], aspect-correct
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // We define a 12-second total cycle:
    //  0..4 sec : N -> E
    //  4..8 sec : E -> O
    //  8..12 sec: O -> N
    float fullCycle = 12.0;
    float t = mod(iTime, fullCycle);

    // Each segment is 4 seconds. 
    int   iCur  = int(floor(t / 4.0));         // [0..2]
    int   iNext = (iCur + 1) % 3;              // next letter
    float f     = fract(t / 4.0);             // [0..1] within the segment

    // Cosine easing (slow in/out)
    float ease = 0.5 * (1.0 - cos(3.14159 * f)); // 0..1

    // SDF for current + next letter
    float dA = letterSDF(uv, iCur);
    float dB = letterSDF(uv, iNext);

    // Perform shell expansion with eased time
    float d = shapeMorph(dA, dB, ease);

    // Distance-based pastel coloring
    // inside => negative d, outside => positive d
    vec3 colInside  = vec3(0.72, 0.88, 0.93); // pastel cyan
    vec3 colOutside = vec3(0.95, 0.90, 0.80); // warm beige
    vec3 baseCol    = (d > 0.0) ? colOutside : colInside;

    // Subtle "fog out" from boundary
    baseCol *= 1.0 - exp(-1.5 * abs(d));

    // Low-frequency wave effect
    baseCol *= 0.9 + 0.1 * cos(160.0 * d);

    // Light highlight near boundary
    baseCol = mix(baseCol, vec3(1.0), 1.0 - smoothstep(0.0, 0.008, abs(d)));

    fragColor = vec4(baseCol, 1.0);
}
